$ErrorActionPreference='SilentlyContinue'
$root='C:\Users\Xxkan'
$c=@()
$known=@(
 (Join-Path $root 'GitHub\mhw-mods'),
 (Join-Path $root 'Documents\GitHub\mhw-mods'),
 (Join-Path $root 'source\repos\mhw-mods'),
 (Join-Path $root 'Desktop\mhw-mods')
)
foreach($p in $known){if(Test-Path (Join-Path $p '.git')){$c+=$p}}
if($c.Count -eq 0){
 $c=@(Get-ChildItem -Path $root -Directory -Filter 'mhw-mods' -Recurse -ErrorAction SilentlyContinue | Where-Object{Test-Path (Join-Path $_.FullName '.git')} | Select-Object -ExpandProperty FullName -First 20)
}
$out=@()
foreach($p in $c){
 Push-Location $p
 $url=(git remote get-url origin 2>$null)
 Pop-Location
 if($url -match 'fengie/mhw-mods'){$out+=[pscustomobject]@{path=$p;origin=$url}}
}
$out|ConvertTo-Json -Depth 3
